import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.DGzMGr_a.js";const p=JSON.parse('{"title":"RO3 亮相 GDC 2026：腾讯云架构支持百万玩家同服","description":"GDC 2026游戏开发者大会上，RO3开发团队JoyMaker分享了游戏弹性云架构，支持百万级CCU并发，由腾讯云提供技术支持。","frontmatter":{"title":"RO3 亮相 GDC 2026：腾讯云架构支持百万玩家同服","date":"2026-05-21T00:00:00.000Z","description":"GDC 2026游戏开发者大会上，RO3开发团队JoyMaker分享了游戏弹性云架构，支持百万级CCU并发，由腾讯云提供技术支持。"},"headers":[],"relativePath":"news/gdc-cloud-202603.md","filePath":"news/gdc-cloud-202603.md","lastUpdated":1779768823000}'),n={name:"news/gdc-cloud-202603.md"};function d(l,t,i,s,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ro3-亮相-gdc-2026-腾讯云架构支持百万玩家同服" tabindex="-1">RO3 亮相 GDC 2026：腾讯云架构支持百万玩家同服 <a class="header-anchor" href="#ro3-亮相-gdc-2026-腾讯云架构支持百万玩家同服" aria-label="Permalink to &quot;RO3 亮相 GDC 2026：腾讯云架构支持百万玩家同服&quot;">​</a></h1><p><strong>2026年5月21日</strong></p><p>在2026年3月于旧金山举办的GDC（Game Developers Conference）大会上，RO3开发团队JoyMaker的技术总监杨超和技术VP耿一婷发表了题为《RO3：支持百万CCU的弹性MMO云架构演进与实践》的演讲。</p><h2 id="核心亮点" tabindex="-1">核心亮点 <a class="header-anchor" href="#核心亮点" aria-label="Permalink to &quot;核心亮点&quot;">​</a></h2><h3 id="百万级并发架构" tabindex="-1">百万级并发架构 <a class="header-anchor" href="#百万级并发架构" aria-label="Permalink to &quot;百万级并发架构&quot;">​</a></h3><p>演讲中透露，RO3采用了<strong>腾讯云</strong>的弹性云架构，目标支持<strong>百万级CCU（Concurrent Concurrent Users，同时在线玩家）</strong>。这一架构经过了从单服务器到水平可扩展跨服架构的演进。</p><h3 id="关键技术" tabindex="-1">关键技术 <a class="header-anchor" href="#关键技术" aria-label="Permalink to &quot;关键技术&quot;">​</a></h3><ul><li><strong>AvatarService集中化</strong>：确保玩家状态在动态迁移过程中的无缝连续性</li><li><strong>Kubernetes自动伸缩</strong>：基于智能监控的自动化运维系统</li><li><strong>水平扩展架构</strong>：从单服到跨服架构的演进</li></ul><h3 id="演讲要点" tabindex="-1">演讲要点 <a class="header-anchor" href="#演讲要点" aria-label="Permalink to &quot;演讲要点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>云平台</td><td>腾讯云（Tencent Cloud）</td></tr><tr><td>容器编排</td><td>Kubernetes（K8s）</td></tr><tr><td>玩家状态管理</td><td>集中式AvatarService</td></tr><tr><td>弹性伸缩</td><td>基于遥测数据的自动扩缩容</td></tr><tr><td>目标CCU</td><td>百万级同时在线</td></tr></tbody></table><h2 id="意义" tabindex="-1">意义 <a class="header-anchor" href="#意义" aria-label="Permalink to &quot;意义&quot;">​</a></h2><p>这一技术分享表明：</p><ol><li>RO3的服务器架构已经经过了大规模压力测试</li><li>腾讯云的参与意味着国服将有强大的基础设施支持</li><li>百万CCU的目标说明Gravity对RO3的用户规模有很高期待</li></ol><h2 id="演讲受众定位" tabindex="-1">演讲受众定位 <a class="header-anchor" href="#演讲受众定位" aria-label="Permalink to &quot;演讲受众定位&quot;">​</a></h2><p>该演讲被标记为「高级」级别，目标受众为服务器工程师和技术负责人，内容涵盖MMO后端架构、云原生实践和Kubernetes运维。</p><blockquote><p>来源：<a href="https://schedule.gdconf.com/session/ragnarok-online-3-the-evolution-and-practice-of-elastic-mmo-cloud-architecture-supporting-million-ccu-presented-by-tencent-games/917934" target="_blank" rel="noreferrer">GDC Festival of Gaming 2026 议程</a></p></blockquote>',16)])])}const C=e(n,[["render",d]]);export{p as __pageData,C as default};
